This is what I used to create those packets:
```c
#include <stdio.h>
#include <string.h>
#include <mysql.h>

MYSQL mysql;

int main() {
  MYSQL_BIND bind[2];
  char *mystr = "test test";
  const char *name[2] = {"foo", "bar"};
  unsigned int ssl_mode = SSL_MODE_DISABLED;
  unsigned long long intparam = 18446744073709551615ULL;

  mysql_init(&mysql);

  mysql_options(&mysql,MYSQL_OPT_SSL_MODE, &ssl_mode);
  if (!mysql_real_connect(&mysql, "127.0.0.1", "root", "", "test", 0, NULL, 0)) {
    fprintf(stderr, "Failed to connect to database: Error: %s\n",
            mysql_error(&mysql));
  }

  memset(bind, 0, sizeof(bind));

  unsigned long mystrlen = strlen(mystr);
  bind[0].buffer_type = MYSQL_TYPE_STRING;
  bind[0].buffer = mystr;
  bind[0].length = &mystrlen;
  bind[0].is_null = 0;

  unsigned long intparamlen = sizeof(long long int);
  bind[1].buffer_type = MYSQL_TYPE_LONGLONG;
  bind[1].buffer = (char *) &intparam;
  bind[1].length = &intparamlen;
  bind[1].is_null = 0;
  bind[1].is_unsigned = 1;
  mysql_bind_param(&mysql, 2, bind, name);

  const char *query = "SELECT mysql_query_attribute_string('foo'), mysql_query_attribute_string('bar')";
  mysql_real_query(&mysql, query, strlen(query));
  MYSQL_RES *result = mysql_store_result(&mysql);
  MYSQL_ROW row = mysql_fetch_row(result);
  unsigned long *lengths = mysql_fetch_lengths(result);
  for(int i = 0; i < 2; i++)
  {
      printf("attribute %d: [%.*s]\n", i+1, (int) lengths[i], row[i] ? row[i] : "NULL");
  }
  mysql_free_result(result);

  mysql_close(&mysql);
}
```

I was able to re-use more existing code, which is good.

Now decoding of all types seems to work.

